{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10", "C15", "C24", "C03", "C13", "C01", "C04", "C26", "C25", "C36", "C37", "C41", "C47"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C15", "C24", "C03", "C13", "C01", "C04", "C26", "C25"],
  "claims": [
    {
      "claim": "Cladribine, a 2-halogenated adenine nucleoside, had absolute oral bioavailability of 36–46% in fasted patients, supporting F ≥20% for the analogous 2-fluoroadenine nucleoside.",
      "card_ids": ["C10", "C15", "C24"]
    },
    {
      "claim": "Didanosine, a purine nucleoside with relatively low fasted F (22–28%), still exceeded the 20% threshold, indicating that even poorly absorbed purine nucleosides can meet the threshold.",
      "card_ids": ["C03", "C13"]
    },
    {
      "claim": "Polar pyrimidine nucleosides lamivudine and emtricitabine had high fasted oral bioavailability (69–95% and 92%), showing that high polarity does not preclude F ≥20%.",
      "card_ids": ["C01", "C04", "C26"]
    },
    {
      "claim": "Zalcitabine absolute oral bioavailability was 80% in fasted patients and 30% in fasted mice; both exceed the 20% threshold, though the mouse value is lower.",
      "card_ids": ["C25", "C41"]
    },
    {
      "claim": "Additional L2 records for lamivudine (93±15%, 86±17%) and emtricitabine (92%) reinforce high oral bioavailability for polar nucleosides.",
      "card_ids": ["C36", "C37", "C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C36", "C37", "C41", "C47"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "not_applicable",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C29", "C30", "C31", "C32", "C33", "C34", "C35", "C38", "C39", "C40", "C42", "C43", "C44", "C45", "C46", "C48"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "The query sugar is a pyranose, whereas most nucleoside records are furanose nucleosides, so structural transferability is moderate rather than exact.",
    "No direct permeability, transporter, intestinal metabolism, or first-pass extraction data are available for the query.",
    "Some supporting records are from mice rather than humans, adding species uncertainty.",
    "The physicochemical prior is mixed, with unfavorable passive permeability but favorable solubility and possible nucleoside-transporter involvement."
  ],
  "decision_summary": "The query is a polar 2-fluoroadenine nucleoside. The closest analog cladribine (36–46%) and other nucleoside analogs (didanosine 22–28%, lamivudine 69–95%, emtricitabine 92%, zalcitabine 30–80%) all show absolute oral bioavailability ≥20%. New L2 records reinforce this direction. No affirmative evidence supports F <20%, so the better-supported prediction is high."
}

